import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.math.stat.Frequency#getPct(Object)
 */
public class Frequency_getPct_TriageGen1Test {

    private Frequency frequency;

    @Before
    public void setUp() {
        frequency = new Frequency();
    }

    @Test
    public void testGetPctWithInteger() {
        frequency.addValue(1);
        frequency.addValue(1);
        frequency.addValue(2);
        // Total count = 3. Frequency of 1 is 2. 2/3 = 0.666...
        double expected = 2.0 / 3.0;
        Assert.assertEquals(expected, frequency.getPct(Integer.valueOf(1)), 1e-10);
    }














}

